//! Browser bindings around a WASM-linked `bridge_cffi`.
//!
//! Generated bytecode and protobuf-encoded calls cross this small wasm-bindgen
//! surface; execution and result-envelope encoding stay in the shared CFFI core.

#[cfg(target_arch = "wasm32")]
use wasm_bindgen::prelude::*;

#[cfg(target_arch = "wasm32")]
mod errors;
#[cfg(target_arch = "wasm32")]
pub mod handle;
#[cfg(target_arch = "wasm32")]
pub mod host_value;
#[cfg(target_arch = "wasm32")]
pub mod media;
#[cfg(target_arch = "wasm32")]
pub mod runtime;
#[cfg(target_arch = "wasm32")]
mod version;

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(start)]
pub fn init() -> Result<(), JsValue> {
    bridge_cffi::register_bridge(bridge_cffi::BridgeInfo {
        language: bridge_cffi::BridgeLanguage::Web,
        bridge_runtime_name: version::BRIDGE_RUNTIME_NAME.to_string(),
        bridge_runtime_version: version::BRIDGE_RUNTIME_VERSION.to_string(),
        toolchain_version: version::TOOLCHAIN_VERSION.to_string(),
    })
    .map(|_| ())
    .map_err(|error| JsValue::from_str(&error))
}

/// Configure the workerd-only non-cryptographic `UUIDv4` source before a
/// generated SDK stages bytecode at module scope.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = configureWorkerdUuidSeed)]
pub fn configure_workerd_uuid_seed(seed: u64) -> Result<(), JsValue> {
    bex_prof_store::ids::configure_workerd_uuid_seed(seed).map_err(JsValue::from_str)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = newFunctionCall)]
pub fn new_function_call() -> u64 {
    bridge_cffi::new_function_call_id()
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = cancelFunctionCall)]
pub fn cancel_function_call(call_id: u64) -> bool {
    bridge_cffi::cancel_function_call_by_id(call_id)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getVersion)]
pub fn get_version() -> String {
    get_toolchain_version()
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getToolchainVersion)]
pub fn get_toolchain_version() -> String {
    version::TOOLCHAIN_VERSION.to_string()
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getBridgeRuntimeVersion)]
pub fn get_bridge_runtime_version() -> String {
    version::BRIDGE_RUNTIME_VERSION.to_string()
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = flushEvents)]
pub fn flush_events() {}
